#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        int ostatnia = liczba % 10;
        int kopia = liczba;
        while (kopia >= 10) kopia /= 10;
        int pierwsza = kopia;
        cout << liczba << ": pierwsza=" << pierwsza
             << ", ostatnia=" << ostatnia;
        if (pierwsza == ostatnia) {
            cout << " -> TAK" << endl;
            ile++;
        } else {
            cout << " -> NIE" << endl;
        }
    }
    cout << "Liczb z rowna pierwsza i ostatnia cyfra: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Ostatnia cyfra to reszta z dzielenia przez 10. Pierwsza cyfra: dzielimy przez 10 w petli dopoki liczba >= 10 — zostaje pierwsza cyfra.

